import java.text.Normalizer;
import java.util.Arrays;
import java.util.List;
import java.util.Locale;
import java.util.Set;

/**
 * A filter over the customer list, as understood by {@link CustomerRepository}.
 *
 * <p>A customer matches when every name term is a substring of the first name
 * or the last name (ignoring case and accents), and its status is one of
 * {@link #statuses}, or {@link #statuses} is empty.
 *
 * @param nameTerms normalized, non-empty search terms; empty means "match any name"
 * @param statuses  statuses to accept; empty means "match any status"
 */
public record CustomerFilter(List<String> nameTerms, Set<CustomerStatus> statuses) {

    public static final CustomerFilter NONE = new CustomerFilter(List.of(), Set.of());

    public CustomerFilter {
        nameTerms = List.copyOf(nameTerms);
        statuses = Set.copyOf(statuses);
    }

    /** Builds a filter from raw user input: a free-text name query and a set of statuses. */
    public static CustomerFilter of(String nameQuery, Set<CustomerStatus> statuses) {
        List<String> terms = nameQuery == null || nameQuery.isBlank()
                ? List.of()
                : Arrays.stream(nameQuery.trim().split("\\s+"))
                        .map(CustomerFilter::normalize)
                        .toList();
        return new CustomerFilter(terms, statuses == null ? Set.of() : statuses);
    }

    public boolean matches(Customer customer) {
        return matchesStatus(customer) && matchesName(customer);
    }

    private boolean matchesStatus(Customer customer) {
        return statuses.isEmpty() || statuses.contains(customer.status());
    }

    private boolean matchesName(Customer customer) {
        if (nameTerms.isEmpty()) {
            return true;
        }
        String haystack = normalize(customer.firstName() + " " + customer.lastName());
        return nameTerms.stream().allMatch(haystack::contains);
    }

    private static String normalize(String s) {
        String withoutAccents = Normalizer.normalize(s, Normalizer.Form.NFD).replaceAll("\\p{M}", "");
        return withoutAccents.toLowerCase(Locale.ROOT);
    }
}
