@SpringBootTest(classes = Application.class, webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
class CustomerListViewBrowserTest extends AbstractBasePlaywrightIT {

    @LocalServerPort
    private int port;

    @Autowired
    private QueryLog queryLog;

    @Override
    public String getUrl() {
        return "http://localhost:" + port;
    }

    @BeforeEach
    void clearLog() {
        queryLog.clear();
    }

    private TextFieldElement nameFilter() {
        return new TextFieldElement(getPage().locator("vaadin-text-field").first());
    }

    private MultiSelectComboBoxElement statusFilter() {
        return MultiSelectComboBoxElement.getByLabel(getPage(), "Status");
    }

    @Test
    void typingANameCostsAtMostTwoQueries() {
        GridElement grid = GridElement.get(getPage());
        Locator input = nameFilter().getInputLocator();
        queryLog.clear();

        input.pressSequentially("Aaltonen", new Locator.PressSequentiallyOptions().setDelay(60));
        grid.waitForGridToStopLoading();

        assertTrue(queryLog.countQueries().size() <= 2,
                "Typing a 9-letter name cost " + queryLog.countQueries().size() + " count queries");
        assertTrue(queryLog.pageQueries().size() <= 2,
                "Typing a 9-letter name cost " + queryLog.pageQueries().size() + " page queries");
        assertTrue(grid.getTotalRowCount() > 0);
        assertTrue(grid.getTotalRowCount() < 500);
    }

    @Test
    void changingTheFilterUpdatesTheAddressBar() {
        GridElement grid = GridElement.get(getPage());

        nameFilter().setValue("vir");
        statusFilter().selectItems("ACTIVE", "CLOSED");
        grid.waitForGridToStopLoading();
        getPage().waitForTimeout(400);

        String url = getPage().url();
        assertTrue(url.contains("name=vir"), url);
        assertTrue(url.contains("status=ACTIVE") && url.contains("CLOSED"), url);
    }

